package migrate

import (
	"database/sql"
	"fmt"
)

// Run adds the orders.status column and backfills it.
//
// Run is safe to rerun after a partial failure: the column is only added if
// missing, only orders with a NULL status are backfilled, and each order's
// event insert and status update commit together. The event insert is also
// guarded, so an order left with an event but no status by an earlier,
// non-transactional run does not get a second event.
func Run(db *sql.DB) error {
	if err := addStatusColumn(db); err != nil {
		return fmt.Errorf("add column: %w", err)
	}
	ids, err := pendingOrderIDs(db)
	if err != nil {
		return fmt.Errorf("list pending orders: %w", err)
	}
	for _, id := range ids {
		if err := backfill(db, id); err != nil {
			return fmt.Errorf("backfill order %d: %w", id, err)
		}
	}
	return nil
}

// addStatusColumn adds orders.status unless it already exists. Probing with a
// zero-row SELECT works across SQL dialects, unlike ADD COLUMN IF NOT EXISTS.
func addStatusColumn(db *sql.DB) error {
	if rows, err := db.Query(`SELECT status FROM orders LIMIT 0`); err == nil {
		return rows.Close()
	}
	_, err := db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`)
	return err
}

func pendingOrderIDs(db *sql.DB) ([]int, error) {
	rows, err := db.Query(`SELECT id FROM orders WHERE status IS NULL`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var ids []int
	for rows.Next() {
		var id int
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	return ids, rows.Err()
}

func backfill(db *sql.DB, id int) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.Exec(`INSERT INTO order_events (order_id, kind)
		SELECT ?, 'backfilled'
		WHERE NOT EXISTS (SELECT 1 FROM order_events WHERE order_id = ? AND kind = 'backfilled')`, id, id); err != nil {
		return err
	}
	if _, err := tx.Exec(`UPDATE orders SET status = 'open' WHERE id = ? AND status IS NULL`, id); err != nil {
		return err
	}
	return tx.Commit()
}

